internal fun <T> withPlatformFile(action: (File)->T): T = if(dib) DibCodec.withBmpFile(file,action) else action(file)

fun checkImport(policy: ImageMemoryPolicy,plan: ImportPlan,residentPixels: Long)=memoryRequirements.checkImport(policy,plan,residentPixels)
fun suggestResize(policy: ImageMemoryPolicy,residentPixels: Long,maxScale: Double=1.0)=memoryRequirements.suggestResize(dimensions,policy,residentPixels,maxScale)

fun decode(plan: ImportPlan,workingBytes: Long=ImageMemoryPolicy.forRuntime().workingBytes,residentPixels: Long=0): Bitmap {
    if (estimatedBytes(plan,residentPixels)>workingBytes) throw ImageSizeException(ui(R.string.ui_the_decoder_and_editing_buffers_need_about_the,
        memoryLabel(estimatedBytes(plan,residentPixels)),memoryLabel(workingBytes.toDouble())))
    val decoderBudget=memoryRequirements.decoderBudget(workingBytes,plan.target,residentPixels)
    if(jxl) return JxlCodec.decode(file,plan.target,decoderBudget)
    if(heif) return HeifCodec.decode(file,plan.target,decoderBudget)
    if(tiff) return TiffCodec.decode(file,plan.target,decoderBudget,pageIndex=pageIndex)
    if(pdf) return PdfCodec.decode(file,plan.target,decoderBudget,pageIndex=pageIndex)
    if(ico) return IcoCodec.decode(file,plan.target,decoderBudget)
    var decoded: Bitmap? = null
    var output: Bitmap? = null
    try {
        val colour = checkNotNull(platformColour)
        val raw = withPlatformFile { platformFile -> colour.withDecodeFile(platformFile) { BitmapFactory.decodeFile(it.path,colour.options(plan.sample)) } }
            ?: throw IOException(ui(R.string.ui_android_could_not_decode_this_image))
        decoded = raw
        val input = colour.convert(raw)
        if (input !== raw) { raw.recycle(); decoded = input }

fun <T> withDecodeFile(source: File, action: (File) -> T): T {
    if (!explicitConversion) return action(source)
    val temporary = File.createTempFile("colour-input-", ".img", source.parentFile)
    try {
        RandomAccessFile(source,"r").use { input ->
            RandomAccessFile(temporary,"rw").use { output ->
                val buffer = ByteArray(64 * 1024)
                fun copyUntil(end: Long) {
                    while (input.filePointer < end) {
                        val count = input.read(buffer,0,minOf(buffer.size.toLong(),end-input.filePointer).toInt())
                        if (count < 0) throw IOException(ui(R.string.colour_truncated_metadata))
                        output.write(buffer,0,count)
                    }
                }
                omitted.sortedBy { it.first }.forEach { range -> copyUntil(range.first); input.seek(range.last+1) }
                copyUntil(input.length())
                if (format == "WEBP") {
                    val length=output.length()-8
                    output.seek(4); repeat(4) { output.write((length shr (it*8)).toInt() and 255) }
                    // Clear the VP8X ICC flag when the corresponding chunk is removed.
                    output.seek(12)
                    while(output.filePointer+8 <= output.length()) {
                        val type=ByteArray(4); output.readFully(type);val n=readLittle(output)
                        val start=output.filePointer
                        if(String(type,Charsets.US_ASCII)=="VP8X" && n>=1) {val flags=output.read();output.seek(start);output.write(flags and 0xdf);break}
                        output.seek(start+n+(n and 1))
                    }

fun <T> withBmpFile(file: File, block: (File) -> T): T {
    if (!isDib(file)) return block(file)
    val temporary = File.createTempFile("dib-input-", ".bmp", file.absoluteFile.parentFile)
    try {
        readImage {
            temporary.outputStream().buffered().use { PackedDib.toBmp(file, it) }
            LegacyColourMetadata.check(temporary)
        }
        return block(temporary)
    } finally { temporary.delete() }
}
